import logging
from ute_ue.utils.proxy_mngr import ProxiedCfgFileBasedUePool
from ute_ue.config import loggers as ta_ue_logging
from taf.ue.mtk.ue import MtkUe
from taf.ue.mtk.exceptions import ReserveUeFailure

# TODO: What about moving it to versioning.py
# variables used to deploy proxy service via proxy mngr
MIN_REQUIRED_UEPROXY_VER = '1.11.0'
MIN_REQUIRED_ACCESS_VER = '0.9.0'


class TafUeMtkPool(ProxiedCfgFileBasedUePool):

    def __init__(self, config_file_path=None, inline_config=None):
        """

        :param config_file_path:
        :param inline_config:
        """
        self.inline_config = inline_config
        super(TafUeMtkPool, self).__init__(config_file_path, inline_config)
        self.rpc_client = None

        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL'})

    def create_device(self, device_name, device_config):
        """
        Create instance of ue

        :param device_name:
        :param device_config:
        :return: ue instance
        """
        self.logger.debug("executing create_device with name {} and configuration {}".format(device_name, device_config))
        constructor_parameters = device_config["CONSTRUCTOR_PARAMETERS"]
        configuration = constructor_parameters["configuration"]
        configuration["capabilities"] = device_config["CAPABILITIES"]
        ue_id = constructor_parameters["serial_number"]

        self.prepare_ueproxy_service(device_config)
        self.rpc_client = self.get_ueproxy_connection_client_by(configuration['ue_pc_address'])
        mtk_ue = MtkUe(name=device_name, ue_id=ue_id, ue_pc=self.rpc_client, configuration=configuration)
        is_reservation_successful = mtk_ue.prepare_ue()
        if not is_reservation_successful:
            raise ReserveUeFailure("UE {} reservation failed".format(mtk_ue.ue_id))
        return mtk_ue

    def shutdown(self):
        """
        Shutdown

        avoid: RuntimeError: dictionary changed size during iteration
        """
        self.ueproxy_teardown(self.rpc_client)
